def test_find_entities_ignores_masked_values(session, signal_instance, project):
    from dispatch.signal.redaction import MASK

    signal_instance.raw = {
        "session_token": "s3cret-token",
        "nested": [{"Password": "hunter2"}],
        "user": "alice",
    }
    entity_types = [
        EntityType(name="Token", jpath="session_token", regular_expression=None, project=project),
        EntityType(name="Pass", jpath="nested[*].Password", regular_expression=None, project=project),
        EntityType(name="User", jpath="user", regular_expression=None, project=project),
    ]

    # unredacted payload: the sensitive values must still not become entities
    entities = entity_service.find_entities(session, signal_instance, entity_types)
    assert {e.value for e in entities} == {"alice"}

    # already redacted payload: the mask must not become a shared entity
    signal_instance.raw = {**signal_instance.raw, "session_token": MASK}
    entities = entity_service.find_entities(session, signal_instance, entity_types)
    assert {e.value for e in entities} == {"alice"}
E
